WITH valid_shipments AS (SELECT *, ADD_MONTHS(shipped_date, 6) AS shipped_date_plus_months FROM shipments WHERE order_id = 5), summary AS (SELECT QUARTER(delivered_date) AS delivered_quarter, ROUND(AVG(cost), 2) AS avg_cost, ROUND((100 * SUM(CASE WHEN carrier = 'Flash' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_flash FROM valid_shipments GROUP BY QUARTER(delivered_date)) SELECT delivered_quarter, avg_cost, pct_flash FROM summary WHERE pct_flash >= 50 ORDER BY avg_cost DESC
